// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/proxy.sol";

contract StorageContract {
    address public owner;
    uint256 public totalTransactions;
    mapping(address => uint256) public userTransactionCount;

    function initialize() public {
        owner = msg.sender;
    }
}

contract ProxyTest is Test {
    Proxy public proxy;
    StorageContract public storageContract;
    address owner = address(0x1);
    address attacker = address(0x2);

    function setUp() public {
        vm.prank(owner);
        proxy = new Proxy();

        storageContract = new StorageContract();
    }

    function testStorageManipulation() public {
        // Attacker prepares malicious calldata to initialize the storage contract
        bytes memory initData = abi.encodeWithSignature("initialize()");

        // Attacker calls forward with delegatecall to storage contract
        vm.prank(attacker);
        proxy.forward(address(storageContract), initData);

        // Verify storage contract's owner wasn't changed (delegatecall affects proxy's storage)
        assertEq(storageContract.owner(), address(0), "Storage contract owner should remain unchanged");

        // Verify proxy's transaction count was updated
        (bool success, bytes memory data) = address(proxy).staticcall(
            abi.encodeWithSignature("getUserStats(address)", attacker)
        );
        require(success, "Call failed");
        uint256 txCount = abi.decode(data, (uint256));

        assertEq(txCount, 1, "Attacker's transaction count should be 1");
    }

    function testDoubleInitialization() public {
        // First initialization by owner
        bytes memory initData = abi.encodeWithSignature("initialize()");
        vm.prank(owner);
        proxy.forward(address(storageContract), initData);

        // Verify storage contract's owner wasn't changed
        assertEq(storageContract.owner(), address(0), "Storage contract owner should remain unchanged");

        // Second initialization by attacker
        vm.prank(attacker);
        proxy.forward(address(storageContract), initData);

        // Verify attacker's transaction count was incremented
        (bool success, bytes memory data) = address(proxy).staticcall(
            abi.encodeWithSignature("getUserStats(address)", attacker)
        );
        require(success, "Call failed");
        uint256 txCount = abi.decode(data, (uint256));

        assertEq(txCount, 1, "Attacker's transaction count should be 1");
    }
}
